parameters.jsCode:
const data = $json;

const problems = [];

// PostgreSQL
for (const [database, backup] of Object.entries(data.postgres ?? {})) {
  if (backup.status !== 'ok') {
    problems.push({
      component: `postgres.${database}`,
      status: backup.status ?? 'unknown',
      message: `Backup PostgreSQL de ${database} está com status ${backup.status ?? 'unknown'}.`,
      details: backup
    });
  }
}

// Restic
if (data.restic?.status !== 'ok') {
  problems.push({
    component: 'restic',
    status: data.restic?.status ?? 'unknown',
    message: `Backup Restic está com status ${data.restic?.status ?? 'unknown'}.`,
    details: data.restic ?? {}
  });
}

// IMPORTANTE:
// offsite não entra como incidente operacional neste momento.
// Ele permanece apenas como recomendação de resiliência.

const severityRank = {
  unknown: 2,
  warning: 2,
  error: 3,
  critical: 4
};

let severity = 'info';

for (const problem of problems) {
  const currentRank = severityRank[problem.status] ?? 2;
  const selectedRank = severityRank[severity] ?? 1;

  if (currentRank > selectedRank) {
    severity = problem.status === 'unknown'
      ? 'warning'
      : problem.status;
  }
}

const healthy =
  data.healthy === true &&
  problems.length === 0;

return [
  {
    json: {
      should_emit: !healthy,

      source: 'backup_verification',
      severity,

      component: 'backup',

      event: healthy
        ? 'backup_healthy'
        : 'backup_problem',

      status: healthy
        ? 'healthy'
        : 'active',

      timestamp:
        data.checked_at ?? new Date().toISOString(),

      message: healthy
        ? 'Os backups do OMEAB estão funcionando normalmente.'
        : `${problems.length} problema(s) encontrado(s) no sistema de backup do OMEAB.`,

      details: {
        postgres: data.postgres ?? {},
        restic: data.restic ?? {},
        offsite: data.offsite ?? {},
        problems
      },

      requires_attention: !healthy,

      suggested_action: healthy
        ? null
        : 'Verificar os componentes de backup indicados em details.problems.',

      backup_state: {
        healthy,
        problem_count: problems.length,
        offsite_configured:
          data.offsite?.configured ?? false
      }
    }
  }
];

const data = $json;

const previousEvent = data.previous_event ?? null;
const previousSeverity = data.previous_severity ?? null;
const previousStatus = data.previous_status ?? null;

let shouldNotify = false;
let reason = 'no_change';

// 1. PRIMEIRO INCIDENTE
if (
  previousEvent === null &&
  data.should_emit === true
) {
  shouldNotify = true;
  reason = 'first_incident';
}

// 2. RECUPERAÇÃO
if (
  data.event === 'backup_healthy' &&
  previousEvent !== null &&
  previousStatus !== 'healthy'
) {
  return [
    {
      json: {
        ...data,

        should_emit: true,
        severity: 'info',
        event: 'backup_recovered',
        status: 'healthy',

        message:
          `Os backups do OMEAB voltaram a operar normalmente. ` +
          `O estado anterior era: ${previousEvent}.`,

        requires_attention: false,

        suggested_action:
          'Nenhuma ação imediata necessária. Continuar monitorando as próximas execuções de backup.',

        notification: {
          should_notify: true,
          reason: 'recovered',
          previous_event: previousEvent,
          previous_severity: previousSeverity,
          previous_status: previousStatus
        }
      }
    }
  ];
}

// 3. MUDANÇA NO TIPO DE INCIDENTE
if (
  data.should_emit === true &&
  previousEvent !== null &&
  data.event !== previousEvent
) {
  shouldNotify = true;
  reason = 'incident_changed';
}

// 4. ESCALADA DE SEVERIDADE
if (
  data.should_emit === true &&
  previousEvent !== null &&
  data.event === previousEvent
) {
  const severityRank = {
    info: 1,
    warning: 2,
    error: 3,
    critical: 4
  };

  const currentRank =
    severityRank[data.severity] ?? 0;

  const previousRank =
    severityRank[previousSeverity] ?? 0;

  if (currentRank > previousRank) {
    shouldNotify = true;
    reason = 'severity_escalated';
  }
}

return [
  {
    json: {
      ...data,

      notification: {
        should_notify: shouldNotify,
        reason,
        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus
      }
    }
  }
];

